// ========== 工具函数 ==========
export function getWordBook(bookId) {
  return wordBooks.find(b => b.id === bookId)
}

export function getWordsByBook(bookId) {
  const book = getWordBook(bookId)
  return book ? book.words : []
}

export function getRandomWords(bookId, count = 10, excludeIds = []) {
  const words = getWordsByBook(bookId).filter(w => !excludeIds.includes(w.id))
  const shuffled = [...words].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, Math.min(count, shuffled.length))
}

export function getWordById(bookId, wordId) {
  const words = getWordsByBook(bookId)
  return words.find(w => w.id === wordId)
}